{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C08"],
      "claim": "The closest analogue, a piperazine-anilinopyrimidine fused heterocycle, has an oral bioavailability of approximately 20–25% in patients, meeting the F ≥ 20% threshold and supporting a high prediction.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "A cyclopentyl-containing fused heterocycle with a similar lipophilic core was predicted to have 80% absolute oral bioavailability in humans, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Brigatinib, which shares the piperazine-aniline-aminopyrimidine motif, has 57% absolute oral bioavailability in the fasted state in healthy volunteers, directly supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Brepocitinib, a heteroaromatic kinase inhibitor, has approximately 75% absolute oral bioavailability in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Imatinib, containing a piperazine and aminopyrimidine, is almost completely absorbed with 98% absolute oral bioavailability, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Fasudil, a heteroaromatic sulfonamide with a cyclic diamine, has 69% absolute oral bioavailability in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Risdiplam, a heteroaromatic drug with a piperazine-like amine, has high oral bioavailability due to complete absorption and negligible first-pass metabolism, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Niraparib, an orally absorbed heteroaromatic drug, has approximately 73% absolute bioavailability in fasted patients, supporting high F.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Prediction: high. Multiple transferable experimental analogues with shared piperazine-aniline-aminopyrimidine or heteroaromatic features show absolute oral bioavailability from about 20–25% to 98%, consistently above the 20% threshold. The physicochemical prior suggesting low passive absorption is an uncertain estimate and is outweighed by the consistent experimental evidence.",
  "evidence_gaps": [
    "No direct experimental oral bioavailability record for the query molecule; all analogues have Morgan similarity below 0.4.",
    "The closest analogue has borderline F (~20–25%), so the threshold margin is small.",
    "No query-specific permeability, efflux, solubility, or food-effect data are available."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

